// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 gasValue, uint256 blockNum) public {
        // Bound inputs to reasonable values
        vm.assume(gasValue != 0); // avoid division by zero in modulus
        blockNum = bound(blockNum, 1, 1000);
        vm.roll(blockNum);

        // Ensure the condition holds that block.number % 15 == 0
        vm.assume(blockNum % 15 == 0);

        uint256 balanceBefore = address(c).balance;

        // Call fallback with 10 ether
        (bool success, ) = address(c).call{value: 10 ether}("");

        uint256 balanceAfter = address(c).balance;

        // The rule: when block.number % 15 == 0, the balance must not increase
        // (it should either stay same or decrease if transfer happens)
        assertTrue(balanceBefore >= balanceAfter);
    }
}

